<script setup lang="ts">
import { ref, computed, watch, onMounted } from 'vue'
import { ArrowLeftRight, RefreshCw } from '@lucide/vue'
import { notifyError, state, candidate, api, action } from '../store'
import { violations, origin } from '../presentation'
import type { RecordData } from '../types'
import Context from '../components/Context.vue'
import Notice from '../components/Notice.vue'
import Empty from '../components/Empty.vue'
const matches = ref<RecordData[]>([]); const participants = ref<RecordData[]>([]); const participantId = ref(''); const selectedId = ref('')
const share = ref(false)
const rows = computed(() => { const unique = new Map<string, RecordData>(); for (const r of matches.value.filter(r => r.job_id === state.jobId && (!candidate.value || r.resume_id === state.resumeId))) if (!unique.has(r.resume_id)) unique.set(r.resume_id, r); return [...unique.values()] })
const match = computed(() => rows.value.find(r => r.id === selectedId.value) || rows.value[0]); const cfg = computed(() => state.presentation!)
const safe = computed(() => !match.value || [match.value.job_title, match.value.candidate_name, match.value.ambience_text, match.value.basis_statement, ...match.value.dimension_results.flatMap((d: RecordData) => [d.name,d.ent_quote,d.cand_quote,d.unmatched_reason])].every(t => !violations(t, cfg.value, !candidate.value)))
let sequence = 0
async function load() { const ticket = ++sequence; matches.value = []; participants.value = []; const id = state.jobId; try { const [m,p] = await Promise.all([api<RecordData[]>('/matches'), !candidate.value && id ? api<RecordData[]>('/matches/participants?job_id=' + id) : Promise.resolve([])]); if (ticket !== sequence) return; matches.value = m; participants.value = p; if (!p.some(r => r.id === participantId.value)) participantId.value = p[0]?.id || '' } catch(e) { if (ticket === sequence) notifyError(e) } }
onMounted(load); watch(() => [state.jobId,state.resumeId], load)
async function run(resumeId?: string) { await action(async () => { const m = await api('/matches/run', 'POST', { job_id: state.jobId, resume_id: resumeId || (candidate.value ? state.resumeId : participantId.value), share_with_job: candidate.value && share.value }); await load(); selectedId.value = m.id }, '双方偏好已对照，未填写的方面保留为无法判断。') }
</script>
<template>
  <div class="page-heading"><p class="eyebrow">彼此期待 / 双向理解</p><h1>双方偏好对照</h1><p>看见相符的期待，也理解不同选择背后的原意。</p></div><Context :with-resume="candidate"><label v-if="!candidate">已同意参与的求职者<select v-model="participantId"><option value="" disabled>暂无已授权参与者</option><option v-for="p in participants" :key="p.id" :value="p.id">{{ p.display_name }}</option></select></label><button class="primary" @click="run()" :disabled="state.busy || !state.jobId || !(candidate ? state.resumeId : participantId)"><ArrowLeftRight :size="17" />对照双方期待</button></Context><label v-if="candidate" class="check match-consent"><input v-model="share" type="checkbox">我同意向当前岗位招聘方共享我的姓名与本次偏好对照依据；不共享完整简历或个人能力报告。</label><Notice />
  <Empty v-if="!rows.length" title="让双方的期待相遇" text="双方先完成偏好填写与共享授权，再发起对照。无法判断也会明确保留。" to="/preferences" label="填写偏好" />
  <template v-else-if="safe"><div class="participant-strip"><button v-for="m in rows" :key="m.id" :class="['participant-card', { selected: m.id === match?.id }]" @click="selectedId = m.id"><span class="user-avatar">{{ m.candidate_name[0] }}</span><span><strong>{{ m.candidate_name }}</strong><small>{{ origin(m.data_origin) }}</small></span><span :class="['pill', { teal: m.overall_tier === '高' }]">{{ cfg.preference_labels[m.overall_tier] }}</span></button></div><div v-if="match" class="preference-layout"><section class="surface match-body"><div class="detail-heading"><h2>把双方期待放在一起</h2><span :class="['pill', { amber: match.outdated }]">{{ match.outdated ? '基于过期填报' : '当前填报' }}</span></div><div class="match-bridge"><div><small>企业的期待</small><h3>{{ match.job_title }}</h3><p>企业主动填写</p></div><span>↔</span><div><small>个人的期待</small><h3>{{ match.candidate_name }}</h3><p>求职者主动填写</p></div></div><details v-for="d in match.dimension_results.filter((d: RecordData) => d.required)" :key="d.dimension_id || d.id || d.name" class="evidence-detail" open><summary><strong>{{ d.name }}</strong><span class="pill">{{ cfg.preference_labels[d.tier] }}</span></summary><div class="evidence-body"><div class="paired-evidence"><blockquote><small>企业填报原文</small>{{ d.ent_quote || '未填写' }}</blockquote><blockquote><small>求职者填报原文</small>{{ d.cand_quote || '未填写' }}</blockquote></div><p class="muted">{{ d.unmatched_reason || (d.distance === 0 ? '双方选择相同。' : '双方选择存在差异，可在沟通中进一步了解。') }}</p></div></details><details class="evidence-detail"><summary><strong>更多期待 · 协作、反馈与节奏</strong></summary><div class="evidence-body"><article v-for="d in match.dimension_results.filter((d: RecordData) => !d.required)" :key="d.name"><div class="row-between"><h4>{{ d.name }}</h4><span class="pill">{{ cfg.preference_labels[d.tier] }}</span></div><div class="paired-evidence"><blockquote><small>企业填报原文</small>{{ d.ent_quote || '未填写' }}</blockquote><blockquote><small>求职者填报原文</small>{{ d.cand_quote || '未填写' }}</blockquote></div><p class="muted">{{ d.unmatched_reason }}</p></article></div></details><p class="muted">{{ match.basis_statement }}</p><p class="version-line">偏好口径 {{ match.dimension_version }} · 规则 {{ match.engine_version }}</p></section><aside><section class="context-card"><p class="eyebrow">企业自行填写</p><h3>团队氛围</h3><p class="source-text">{{ match.ambience_text || '企业暂未填写氛围描述。' }}</p><small>企业自述与系统对照分别呈现。</small></section><section class="context-card"><h3>让下一次沟通更具体</h3><ol class="conversation-steps"><li>先看相符的偏好。</li><li>展开差异，了解双方原意。</li><li>对未填写的方面继续沟通。</li></ol><p class="muted">偏好由规则直接对照，不使用 AI 猜测。</p><button v-if="match.outdated" class="secondary" :disabled="state.busy" @click="run(match.resume_id)"><RefreshCw :size="15" />重新对照</button></section></aside></div></template><Empty v-else title="结果暂不可展示" text="内容未通过呈现检查，请刷新后重新查看。" /><Notice footer />
</template>
